// Inputs with `opt` and defaults; outputs: a first output called Result is the return value, the rest are `out`.
/// @name Functions/MF_LpSignature
/// @param InColor The colour
/// @param Weight Its weight
export float3 MF_LpSignature(float3 InColor, float Strength = 1.0, float Bias, out float Weight)
{
    float3 Result = float3(0, 0, 0);
    Result = InColor * Strength + Bias;
    Weight = Strength;

    return Result;
}
